<script setup>
import { computed, reactive, ref, watch } from 'vue'; import { Plus, Search, TrendingDown } from 'lucide-vue-next'; import { useAuthStore } from '@/stores/auth'; import { useFinanceStore } from '@/stores/finance'; import { masterDataConfig } from '@/data/masterDataMock'; import { formatCurrency, formatDate } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import BaseModal from '@/components/ui/BaseModal.vue'; import BaseSelect from '@/components/ui/BaseSelect.vue'; import BaseTextarea from '@/components/ui/BaseTextarea.vue'; import Pagination from '@/components/ui/Pagination.vue'; import { useUiStore } from '@/stores/ui';
const finance=useFinanceStore(),auth=useAuthStore(),ui=useUiStore(),search=ref(''),vendorFilter=ref('semua'),categoryFilter=ref('semua'),page=ref(1),modal=ref(false),edit=ref(null),error=ref(''),proof=ref(''),pageSize=5;const accounts=masterDataConfig.account.records.filter(x=>x.status==='aktif'),vendors=masterDataConfig.vendor.records.filter(x=>x.status==='aktif');const blank=()=>({date:'2026-08-28',vendorId:'',category:'',description:'',amount:'',transactionType:'cash',destinationAccountId:null,referenceNumber:'',proofName:'',notes:''});const form=reactive(blank());const readOnly=computed(()=>auth.role==='manager');const vendor=id=>vendors.find(x=>x.id===id);const account=id=>accounts.find(x=>x.id===id);const filtered=computed(()=>finance.expenses.filter(x=>`${vendor(x.vendorId)?.nama||''} ${x.description} ${x.referenceNumber||''}`.toLowerCase().includes(search.value.toLowerCase())&&(vendorFilter.value==='semua'||x.vendorId===vendorFilter.value)&&(categoryFilter.value==='semua'||x.category===categoryFilter.value)));const rows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize));const total=computed(()=>filtered.value.reduce((sum,x)=>sum+x.amount,0));watch([search,vendorFilter,categoryFilter],()=>page.value=1);watch(()=>form.transactionType,(type)=>{if(type!=='transfer')form.destinationAccountId=null});const typeLabel={cash:'Cash',qris:'QRIS',credit:'Credit',transfer:'Transfer'};const openAdd=()=>{edit.value=null;Object.assign(form,blank());proof.value='';error.value='';modal.value=true};const openEdit=item=>{edit.value=item;Object.assign(form,item,{amount:String(item.amount)});proof.value=item.proofName||'';error.value='';modal.value=true};const chooseProof=e=>{proof.value=e.target.files?.[0]?.name||'';form.proofName=proof.value};const save=()=>{try{form.proofName=proof.value;if(edit.value)finance.updateExpense(edit.value.id,form);else finance.addExpense(form);ui.notify(edit.value?'Pengeluaran berhasil diperbarui.':'Pengeluaran berhasil ditambahkan.');modal.value=false}catch(e){error.value=e.message}};
</script>
<template><div class="p-6"><header class="mb-5 flex items-start justify-between"><div><h1 class="text-xl font-semibold text-[#172033]">Pengeluaran</h1><p class="mt-0.5 text-sm text-[#667085]">Pencatatan seluruh pengeluaran dan biaya operasional perusahaan.</p></div><BaseButton v-if="!readOnly" @click="openAdd"><Plus :size="15"/>Tambah Pengeluaran</BaseButton></header><BaseCard class="mb-5 flex items-center justify-between" padding="p-4"><div><p class="text-xs text-[#667085]">Total Pengeluaran</p><p class="text-2xl font-bold text-[#DC2626]">{{formatCurrency(total)}}</p></div><TrendingDown :size="32" class="text-red-200"/></BaseCard><div class="mb-4 flex flex-wrap items-center gap-3"><BaseInput v-model="search" class="max-w-xs flex-1" placeholder="Cari pengeluaran..."><template #prefix><Search :size="14"/></template></BaseInput><BaseSelect v-model="vendorFilter" class="w-44" :options="[{value:'semua',label:'Semua Vendor'},...vendors.map(x=>({value:x.id,label:x.nama}))]"/><BaseSelect v-model="categoryFilter" class="w-40" :options="[{value:'semua',label:'Semua Kategori'},'Infrastruktur','Peralatan','Operasional','Marketing']"/></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><table class="w-full min-w-[1150px]"><thead><tr class="border-b border-[#E2E6EC] bg-[#F9FAFB]"><th v-for="h in ['Tanggal','Vendor','Kategori','Keterangan','Jenis Transaksi','Rekening Tujuan','Nominal','Bukti','Aksi']" :key="h" class="px-4 py-3 text-left text-xs font-medium text-[#667085] first:px-5 last:text-center">{{h}}</th></tr></thead><tbody><tr v-for="expense in rows" :key="expense.id" class="border-b border-[#F3F4F6] hover:bg-gray-50"><td class="px-5 py-3.5 text-sm text-[#667085]">{{formatDate(expense.date)}}</td><td class="px-4 py-3.5 text-sm">{{vendor(expense.vendorId)?.nama||'-'}}</td><td class="px-4 py-3.5"><BaseBadge variant="default">{{expense.category}}</BaseBadge></td><td class="px-4 py-3.5 text-sm">{{expense.description}}</td><td class="px-4 py-3.5"><BaseBadge variant="neutral">{{typeLabel[expense.transactionType]}}</BaseBadge></td><td class="px-4 py-3.5 text-sm text-[#667085]">{{account(expense.destinationAccountId)?.nama||'-'}}</td><td class="px-4 py-3.5 text-right text-sm font-semibold text-red-600">{{formatCurrency(expense.amount)}}</td><td class="px-4 py-3.5 text-xs text-[#667085]">{{expense.proofName||'-'}}</td><td class="px-4 py-3.5 text-center"><button v-if="!readOnly" class="text-xs text-[#315DA8] hover:underline" @click="openEdit(expense)">Edit</button></td></tr></tbody></table><Pagination :page="page" :total="filtered.length" :per-page="pageSize" @change="page=$event"/></section><BaseModal :open="modal" :title="edit?'Edit Pengeluaran':'Tambah Pengeluaran'" size="xl" @close="modal=false"><div class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3"><BaseInput v-model="form.date" label="Tanggal" type="date" required/><BaseSelect v-model="form.vendorId" label="Vendor" :options="[{value:'',label:'- Tanpa Vendor -'},...vendors.map(x=>({value:x.id,label:x.nama}))]"/><BaseSelect v-model="form.category" label="Kategori" :options="[{value:'',label:'Pilih kategori'},'Infrastruktur','Peralatan','Operasional','Marketing']" required/><BaseInput v-model="form.amount" label="Nominal (Rp)" type="number" required/><BaseSelect v-model="form.transactionType" label="Jenis Transaksi" required :options="[{value:'cash',label:'Cash'},{value:'qris',label:'QRIS'},{value:'credit',label:'Credit'},{value:'transfer',label:'Transfer'}]"/><BaseSelect v-if="form.transactionType==='transfer'" v-model="form.destinationAccountId" label="Rekening Tujuan" required :error="error.includes('Rekening tujuan')?error:''" :options="[{value:'',label:'Pilih rekening tujuan'},...accounts.map(x=>({value:x.id,label:`${x.nama} — ${x.nomor} — ${x.atasNama}`}))]"/><BaseInput v-model="form.referenceNumber" label="Nomor Referensi" placeholder="Opsional"/><div><label class="mb-1.5 block text-sm font-medium text-[#172033]">Bukti Transaksi</label><input id="expense-proof" type="file" accept=".jpg,.jpeg,.png,.pdf" class="sr-only" @change="chooseProof"/><label for="expense-proof" class="block cursor-pointer rounded-md border-2 border-dashed border-[#E2E6EC] p-2.5 text-center text-xs text-[#9CA3AF] hover:bg-gray-50">{{proof||'Klik untuk unggah file bukti'}}</label></div><BaseTextarea v-model="form.description" class="md:col-span-2 xl:col-span-3" label="Keterangan" required :rows="3"/><BaseTextarea v-model="form.notes" class="md:col-span-2 xl:col-span-3" label="Catatan" :rows="3"/></div><p v-if="error&&!error.includes('Rekening tujuan')" class="mt-3 text-sm text-red-600">{{error}}</p><template #footer><BaseButton variant="secondary" @click="modal=false">Batal</BaseButton><BaseButton @click="save">Simpan</BaseButton></template></BaseModal></div></template>
